ejemplo:
WITH RECURSIVE nums AS (
  SELECT 1 AS n
  UNION ALL
  SELECT n + 1 FROM nums WHERE n < 10
)
SELECT * FROM nums;

SELECT nombre,
  COALESCE(telefono_movil, telefono_fijo, 'Sin teléfono') AS contacto
FROM clientes;

-- Evita división por cero
SELECT ventas / NULLIF(visitas, 0) AS tasa_conversion
FROM campanas;

SELECT nombre, ventas,
  FIRST_VALUE(nombre) OVER (PARTITION BY region ORDER BY ventas DESC) AS lider
FROM vendedores;

SELECT cliente, total_compras,
  NTILE(4) OVER (ORDER BY total_compras DESC) AS cuartil
FROM resumen_clientes;

SELECT nombre, ventas,
  ROUND(PERCENT_RANK() OVER (ORDER BY ventas) * 100, 1) AS percentil
FROM vendedores;

SELECT nombre,
  DATEDIFF(day, fecha_registro, GETDATE()) AS dias_como_cliente
FROM clientes;

SELECT CAST('2026-04-26' AS DATE) AS fecha,
       TRY_CAST(comentario AS INT)  AS numero_o_null
FROM registros;

formula:
SELECT * FROM tabla
PIVOT (
  AGG(valor) FOR columna IN ([v1],[v2],[v3])
) AS p;

ejemplo:
SELECT * FROM (
  SELECT vendedor, mes, ventas FROM datos
) src
PIVOT (
  SUM(ventas) FOR mes IN ([Ene],[Feb],[Mar])
) AS pvt;

