ejemplo:
SELECT vendedor, mes, ventas
FROM resumen
UNPIVOT (
  ventas FOR mes IN (Ene, Feb, Mar)
) AS u;

-- Calendario de fechas del mes
SELECT fecha::date
FROM GENERATE_SERIES('2026-04-01', '2026-04-30', INTERVAL '1 day') AS t(fecha);

formula:
